using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval — returns JsonTypeInfo<Person> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// 2) Probe without throwing — TryGetTypeInfo returns false if unavailable
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
    Console.WriteLine($"TryGetTypeInfo succeeded: {info!.Type.Name}");

// Now try a type whose metadata we intentionally block via a custom resolver
var restrictedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver
    {
        Modifiers =
        {
            ti => { if (ti.Type == typeof(Secret)) ti.CreateObject = null; }
        }
    }
};

// Use TryGetTypeInfo for the type — it resolves, so it returns true here.
// To show a genuine "not available" case, use an empty resolver:
var emptyOptions = new JsonSerializerOptions
{
    TypeInfoResolver = new EmptyResolver()
};

if (emptyOptions.TryGetTypeInfo(typeof(Secret), out _))
    Console.WriteLine("Secret metadata found (unexpected)");
else
    Console.WriteLine("Secret metadata NOT available — no exception thrown");

// Types
record Person(string Name, int Age);
record Secret(string Value);

// A resolver that resolves nothing
file class EmptyResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) => null;
}

